import os
os.environ['OPENBLAS_NUM_THREADS']='1'
import numpy as np,pandas as pd
from sklearn.model_selection import GroupKFold
from sklearn.metrics import mean_absolute_error
from sklearn.ensemble import ExtraTreesRegressor,HistGradientBoostingRegressor
from catboost import CatBoostRegressor
from joblib import dump
X=pd.read_pickle('/tmp/nlo_X.pkl');meta=pd.read_pickle('/tmp/nlo_meta.pkl');y=pd.read_csv('/work/nlo_dn_train.csv').dn.values
idx=np.where(X.iloc[:200].sym_cubic.values==0)[0]
cols=[c for c in X if not c.startswith(('pair_g','dip_g','raw_','prim_','conv_')) and not (c.startswith(('pair_','dip_')) and c.endswith('_mid'))]
x=X[cols]
splits=list(GroupKFold(n_splits=5,shuffle=True,random_state=31).split(idx,groups=meta.formula.iloc[idx]))
res={}
for trans in ['log02','log10','sqrt','direct']:
 if trans.startswith('log'):
  offset=float(trans[3:])/100;yy=np.log(y+offset);inv=lambda y:np.maximum(0,np.exp(y)-offset)
 elif trans=='sqrt':yy=np.sqrt(y);inv=lambda y:np.maximum(y,0)**2
 else:yy=np.minimum(y,.5);inv=lambda y:np.maximum(y,0)
 for alg in ['et','cat']:
  def mod():
   if alg=='cat':return CatBoostRegressor(iterations=1000,depth=4,learning_rate=.035,l2_leaf_reg=5,verbose=False,thread_count=4,random_seed=19)
   if alg=='et':return ExtraTreesRegressor(n_estimators=600,min_samples_leaf=2,max_features=.8,n_jobs=4,random_state=19)
  cv=np.zeros(200)
  for a,b in splits:
   m=mod();m.fit(x.iloc[idx[a]],yy[idx[a]]);cv[idx[b]]=inv(m.predict(x.iloc[idx[b]]))
  use=(y>.04)&(y<.2)
  mae=np.mean(abs(cv-y));mae2=np.mean(abs(cv[use]-y[use]))
  m=mod();m.fit(x.iloc[idx],yy[idx]);pr=inv(m.predict(x.iloc[200:]));pr[X.iloc[200:].sym_cubic.values==1]=0
  res[trans+'_'+alg]={'cv':cv,'test':pr,'mae':mae,'mae2':mae2}
  print(trans,alg,'mae',round(mae,4),'midmae',round(mae2,4),flush=True)
  dump(res,'/tmp/nlo_moreresults.joblib')
print(pd.DataFrame({'id':np.arange(1,101),'formula':meta.formula.iloc[200:].values,**{k:v['test'] for k,v in res.items()}}).round(4).to_string(index=False))

import os
os.environ['OPENBLAS_NUM_THREADS']='1'
import warnings
warnings.filterwarnings('ignore')
import numpy as np,pandas as pd
from pymatgen.core import Structure
from pymatgen.analysis.structure_matcher import StructureMatcher
from joblib import Parallel,delayed,dump
D=pd.concat([pd.read_csv('/work/nlo_dn_train.csv'),pd.read_csv('/work/nlo_pool.csv')],ignore_index=True);meta=pd.read_pickle('/tmp/nlo_meta.pkl');S=[Structure.from_str(p,fmt='poscar') for p in D.poscar]
M=StructureMatcher(ltol=.4,stol=.5,angle_tol=10,primitive_cell=True,scale=True,attempt_supercell=False)

def chem(a,b):
 if a==b:return 0
 return (.4*abs(a.row-b.row)+.3*abs(a.X-b.X)+(.8 if a.group!=b.group else 0)+.1*min(abs(a.group-b.group),4))

def match(i,j):
 if meta.sg[i]!=meta.sg[j]:return (i,j,[])
 if S[i].composition.anonymized_formula!=S[j].composition.anonymized_formula:return (i,j,[])
 try:
  maps=M.get_all_anonymous_mappings(S[i],S[j],include_dist=True)
  if not maps:return (i,j,[])
  out=[]
  for m,dist in maps:
   cost=sum(S[i].composition.fractional_composition[a]*chem(a,b) for a,b in m.items())
   out.append((cost,dist,{str(a):str(b) for a,b in m.items()}))
  return(i,j,out)
 except:return(i,j,[])
pairs=[(i,j) for i in range(300) for j in range(min(i,200)) if meta.formula[i]!=meta.formula[j] and meta.sg[i]==meta.sg[j] and S[i].composition.anonymized_formula==S[j].composition.anonymized_formula]
print('Pairs',len(pairs),flush=True)
res=Parallel(n_jobs=8,verbose=5)(delayed(match)(i,j) for i,j in pairs);dump(res,'/tmp/nlo_analogs.joblib')
for i in range(200,300):
 mm=[]
 for a,b,c in res:
  if a!=i or not c:continue
  cost,dist,m=min(c,key=lambda q:q[0]+q[1])
  mm.append((cost+dist,b,cost,dist,m))
 if mm:
  print('\n',D.candidate_id[i],meta.formula[i])
  for score,j,cost,dist,m in sorted(mm)[:5]:print(j,meta.formula[j],round(D.dn[j],5),round(cost,3),round(dist,3),m)

